#[verus::spec]
fn binary_search(a: &[i32], key: i32) -> usize {
    // Precondition: The slice `a` must be sorted in non-decreasing order.
    // Requires: a must be a valid slice and key is an i32.
    #[verus::requires(a.len() > 0)]
    #[verus::ensures(0 <= result && result <= a.len())]
    #[verus::ensures(
        forall(|i: usize| (0 <= i && i < result) ==> a[i] < key) &&
        forall(|i: usize| (result <= i && i < a.len()) ==> key <= a[i])
    )]
    let mut left = 0;
    let mut right = a.len();

    // Invariant: left <= right and both are within bounds of the array.
    #[verus::invariant(0 <= left && left <= right && right <= a.len())]
    while left < right {
        let mid = left + (right - left) / 2;

        // Invariant: a[mid] is a valid access.
        #[verus::invariant(0 <= mid && mid < a.len())]
        if a[mid] < key {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left
}

